class CreditException extends \RuntimeException {}

class CreditSchema {
    private static $ready = false;
    public static function namespaces(){return array("davvag_credit_program","davvag_credit_wallet","davvag_credit_transaction","davvag_credit_entry","davvag_credit_lot","davvag_credit_reservation","davvag_credit_package","davvag_credit_purchase_order","davvag_credit_payment_event","davvag_credit_reward_rule","davvag_credit_reward_claim","davvag_credit_coupon_campaign","davvag_credit_coupon_code","davvag_credit_coupon_redemption","davvag_credit_idempotency","davvag_credit_lesson_unlock");}
    public static function ensure(){if(self::$ready)return;foreach(self::namespaces() as$namespace){$result=null;try{$result=\SOSSData::Query($namespace,"",null,"asc",1,0,null,false);}catch(\Throwable$first){try{$result=\SOSSData::Query($namespace,"",null,"asc",1,0,null,false);}catch(\Throwable$second){throw new CreditException("Credit schema could not be initialized: ".$namespace." (".$second->getMessage().")",0,$second);}}if(!$result||!$result->success)throw new CreditException("Credit schema could not be initialized: ".$namespace.(isset($result->message)&&$result->message!==""?" (".$result->message.")":""));}self::$ready=true;}
}

class CreditDatabase {
    private $connection;
    public function __construct(){CreditSchema::ensure();if(!defined("DB_CONFIG_FILE")||!defined("DATASTORE_DOMAIN")||!file_exists(DB_CONFIG_FILE))throw new CreditException("Credit datastore configuration is unavailable.");if(!extension_loaded("mysqli"))throw new CreditException("The mysqli PHP extension is required.");$config=json_decode(file_get_contents(DB_CONFIG_FILE));if(!$config||!isset($config->mysql_server,$config->mysql_username,$config->mysql_password,$config->init_db))throw new CreditException("Credit datastore configuration is invalid.");$database=$config->init_db.str_replace(".","_",DATASTORE_DOMAIN);mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);$this->connection=new \mysqli($config->mysql_server,$config->mysql_username,$config->mysql_password,$database);$this->connection->set_charset("utf8mb4");$this->ensureColumns();$this->ensureIndexes();}
    public function transaction($callback){$this->connection->begin_transaction();try{$result=$callback($this);$this->connection->commit();return$result;}catch(\Throwable$error){$this->connection->rollback();throw$error;}}
    public function one($sql,$types="",$params=array()){$rows=$this->all($sql,$types,$params);return count($rows)?$rows[0]:null;}
    public function all($sql,$types="",$params=array()){$statement=$this->prepare($sql,$types,$params);$statement->execute();$result=$statement->get_result();$rows=array();if($result)while($row=$result->fetch_assoc())$rows[]=(object)$row;$statement->close();return$rows;}
    public function run($sql,$types="",$params=array()){$statement=$this->prepare($sql,$types,$params);$statement->execute();$result=(object)array("id"=>$this->connection->insert_id,"affected"=>$statement->affected_rows);$statement->close();return$result;}
    public function insert($table,$data){$this->identifier($table);$columns=array();$marks=array();$types="";$params=array();foreach($data as$column=>$value){$this->identifier($column);$columns[]="`".$column."`";$marks[]="?";if(is_int($value))$types.="i";else{$types.="s";if(is_array($value)||is_object($value))$value=json_encode($value);} $params[]=$value;}return$this->run("INSERT INTO `".$table."`(".implode(",",$columns).") VALUES(".implode(",",$marks).")",$types,$params)->id;}
    public function updateById($table,$id,$data){$this->identifier($table);$sets=array();$types="";$params=array();foreach($data as$column=>$value){$this->identifier($column);$sets[]="`".$column."`=?";if(is_int($value))$types.="i";else{$types.="s";if(is_array($value)||is_object($value))$value=json_encode($value);} $params[]=$value;}$types.="i";$params[]=intval($id);return$this->run("UPDATE `".$table."` SET ".implode(",",$sets)." WHERE id=?",$types,$params)->affected;}
    private function prepare($sql,$types,$params){$statement=$this->connection->prepare($sql);if($types!==""){$values=array_values($params);$refs=array($types);foreach($values as$key=>&$value)$refs[]=&$value;call_user_func_array(array($statement,"bind_param"),$refs);}return$statement;}
    private function identifier($value){if(!preg_match('/^[A-Za-z0-9_]+$/',$value))throw new CreditException("Unsafe datastore identifier.");}
    private function ensureColumns(){$column=$this->one("SELECT COLUMN_NAME FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='davvag_credit_package' AND column_name='product_id' LIMIT 1");if(!$column)$this->connection->query("ALTER TABLE `davvag_credit_package` ADD COLUMN `product_id` INT NOT NULL DEFAULT 0 AFTER `provider_product_id`");$index=$this->one("SELECT INDEX_NAME FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='davvag_credit_package' AND index_name='idx_credit_package_product' LIMIT 1");if(!$index)$this->connection->query("CREATE INDEX `idx_credit_package_product` ON `davvag_credit_package` (`product_id`)");}
    private function ensureIndexes(){$indexes=array(array("davvag_credit_program","uq_credit_program_code","code"),array("davvag_credit_wallet","uq_credit_wallet_owner","program_id,owner_profile_id,wallet_type"),array("davvag_credit_transaction","uq_credit_transaction_idem","program_id,idempotency_key"),array("davvag_credit_reservation","uq_credit_reservation_idem","program_id,idempotency_key"),array("davvag_credit_package","uq_credit_package_code","program_id,package_code"),array("davvag_credit_purchase_order","uq_credit_purchase_reference","order_reference"),array("davvag_credit_purchase_order","uq_credit_purchase_idem","profile_id,idempotency_key"),array("davvag_credit_payment_event","uq_credit_payment_event","provider,provider_event_id"),array("davvag_credit_reward_rule","uq_credit_reward_rule_code","program_id,rule_code"),array("davvag_credit_reward_claim","uq_credit_reward_claim","rule_id,profile_id,period_key"),array("davvag_credit_coupon_campaign","uq_credit_campaign_code","program_id,campaign_code"),array("davvag_credit_coupon_code","uq_credit_coupon_hash","code_hash"),array("davvag_credit_coupon_redemption","uq_credit_redemption","coupon_code_id,profile_id,period_or_limit_key"),array("davvag_credit_idempotency","uq_credit_idempotency","operation_scope,idempotency_key"),array("davvag_credit_lesson_unlock","uq_credit_lesson_unlock","profile_id,lesson_id"));foreach($indexes as$index){$found=$this->one("SELECT INDEX_NAME FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name=? AND index_name=? LIMIT 1","ss",array($index[0],$index[1]));if(!$found)$this->connection->query("CREATE UNIQUE INDEX `".$index[1]."` ON `".$index[0]."` (".$index[2].")");}}
}

class CreditRules {
    public static function truthy($value){return$value===true||$value===1||$value==="1"||in_array(strtolower(strval($value)),array("true","yes"),true);}
    public static function amount($value){$text=trim(strval($value));if(!preg_match('/^[1-9][0-9]*$/',$text)||strlen($text)>10||intval($text)>1000000000)throw new CreditException("Credit amount must be a positive whole number no greater than 1,000,000,000.");return intval($text);}
    public static function code($value,$max=80){$value=strtoupper(trim(strval($value)));if(!preg_match('/^[A-Z0-9][A-Z0-9_-]{1,'.intval($max-1).'}$/',$value))throw new CreditException("A valid code is required.");return$value;}
    public static function idempotency($value){$value=trim(strval($value));if($value===""||strlen($value)>190||!preg_match('/^[A-Za-z0-9:_\-.]+$/',$value))throw new CreditException("A valid idempotency key is required.");return$value;}
    public static function text($value,$label,$max=190){$value=trim(strval($value));if($value===""||strlen($value)>$max)throw new CreditException($label." is required.");return$value;}
    public static function canonical($value){if(is_object($value))$value=get_object_vars($value);if(is_array($value)){if(count($value)&&array_keys($value)!==range(0,count($value)-1))ksort($value);foreach($value as$key=>$item)$value[$key]=self::canonical($item);}return$value;}
    public static function requestHash($value){return hash("sha256",json_encode(self::canonical($value),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));}
    public static function periodKey($cadence,$timezone){$date=new \DateTimeImmutable("now",new \DateTimeZone($timezone?:"UTC"));switch(strtoupper($cadence)){case"DAILY":return$date->format("Y-m-d");case"WEEKLY":return$date->format("o-\\WW");case"MONTHLY":return$date->format("Y-m");default:throw new CreditException("Unsupported reward cadence.");}}
    public static function normalizeCoupon($code){return strtoupper(preg_replace('/[^A-Za-z0-9]/','',strval($code)));}
}

class CreditLedgerService {
    private $db;
    public function __construct($db=null){$this->db=$db?:new CreditDatabase();$this->ensureDefaultProgram();}
    public function database(){return$this->db;}
    public function ensureDefaultProgram(){return$this->db->transaction(function($db){$program=$db->one("SELECT * FROM davvag_credit_program WHERE code='CREDIT' LIMIT 1 FOR UPDATE");if(!$program){$id=$db->insert("davvag_credit_program",array("code"=>"CREDIT","name"=>"Credits","description"=>"Default DAVVAG virtual credits","symbol"=>"C","precision"=>0,"timezone"=>date_default_timezone_get(),"allow_negative_balance"=>"false","spending_policy"=>"EXPIRING_PROMOTIONAL_FIRST","purchase_available"=>"true","reward_available"=>"true","coupon_available"=>"true","purchased_credits_expire"=>"false","default_reward_expiry_days"=>0,"status"=>"ACTIVE"));$program=$db->one("SELECT * FROM davvag_credit_program WHERE id=?","i",array($id));}foreach(array("PURCHASE_ISSUANCE","REWARD_ISSUANCE","COUPON_ISSUANCE","ADMIN_ADJUSTMENT","SPEND_DESTINATION","REFUND_CLEARING","EXPIRATION_CLEARING")as$type)$this->ensureWalletRow($db,$program,0,$type);return$program;});}
    private function programIn($db,$code="CREDIT",$lock=false){$code=CreditRules::code($code,40);$program=$db->one("SELECT * FROM davvag_credit_program WHERE code=? AND status='ACTIVE' LIMIT 1".($lock?" FOR UPDATE":""),"s",array($code));if(!$program)throw new CreditException("Credit program is unavailable.");return$program;}
    public function program($code="CREDIT"){return$this->programIn($this->db,$code,false);}
    private function ensureWalletRow($db,$program,$owner,$type){$wallet=$db->one("SELECT * FROM davvag_credit_wallet WHERE program_id=? AND owner_profile_id=? AND wallet_type=? LIMIT 1 FOR UPDATE","iis",array($program->id,intval($owner),$type));if(!$wallet){$id=$db->insert("davvag_credit_wallet",array("program_id"=>intval($program->id),"owner_profile_id"=>intval($owner),"wallet_type"=>$type,"posted_balance"=>0,"reserved_balance"=>0,"available_balance"=>0,"balance_version"=>0,"status"=>"ACTIVE","suspended_reason"=>""));$wallet=$db->one("SELECT * FROM davvag_credit_wallet WHERE id=? FOR UPDATE","i",array($id));}return$wallet;}
    public function wallet($profileId,$programCode="CREDIT"){if(intval($profileId)<1)throw new CreditException("An active profile is required.");return$this->db->transaction(function($db)use($profileId,$programCode){return$this->ensureWalletRow($db,$this->programIn($db,$programCode,true),intval($profileId),"USER_WALLET");});}
    private function assertWallet($wallet){if(!$wallet||strtoupper($wallet->status)!=="ACTIVE")throw new CreditException("The credit wallet is unavailable.");}
    public function summary($profileId,$programCode="CREDIT"){$wallet=$this->wallet($profileId,$programCode);$program=$this->program($programCode);$purchased=$this->db->one("SELECT COALESCE(SUM(remaining_amount),0) amount FROM davvag_credit_lot WHERE wallet_id=? AND status='ACTIVE' AND remaining_amount>0 AND source_type='PURCHASE'","i",array($wallet->id));$promo=$this->db->one("SELECT COALESCE(SUM(remaining_amount),0) amount FROM davvag_credit_lot WHERE wallet_id=? AND status='ACTIVE' AND remaining_amount>0 AND source_type<>'PURCHASE'","i",array($wallet->id));$soon=$this->db->one("SELECT COALESCE(SUM(remaining_amount),0) amount FROM davvag_credit_lot WHERE wallet_id=? AND status='ACTIVE' AND remaining_amount>0 AND expires_at IS NOT NULL AND expires_at<=DATE_ADD(NOW(),INTERVAL 30 DAY)","i",array($wallet->id));return(object)array("programCode"=>$program->code,"symbol"=>$program->symbol,"walletId"=>intval($wallet->id),"postedBalance"=>intval($wallet->posted_balance),"reservedBalance"=>intval($wallet->reserved_balance),"availableBalance"=>intval($wallet->available_balance),"purchasedBalance"=>intval($purchased->amount),"promotionalBalance"=>intval($promo->amount),"expiringSoon"=>intval($soon->amount),"balanceVersion"=>intval($wallet->balance_version),"status"=>$wallet->status);}
    public function canAfford($profileId,$amount,$programCode="CREDIT"){$amount=CreditRules::amount($amount);$balance=$this->summary($profileId,$programCode);return(object)array("canAfford"=>$balance->availableBalance>=$amount,"amount"=>$amount,"balance"=>$balance);}
    private function normalizeContext($context){if(is_object($context))$context=get_object_vars($context);foreach(array("sourceApp","referenceType","referenceId","idempotencyKey","description")as$key)if(!isset($context[$key]))throw new CreditException($key." is required.");$context["sourceApp"]=CreditRules::text($context["sourceApp"],"sourceApp",100);$context["referenceType"]=CreditRules::text($context["referenceType"],"referenceType",80);$context["referenceId"]=CreditRules::text($context["referenceId"],"referenceId",190);$context["idempotencyKey"]=CreditRules::idempotency($context["idempotencyKey"]);$context["description"]=CreditRules::text($context["description"],"description",1000);return$context;}
    private function beginIdempotency($db,$scope,$key,$payload){$hash=CreditRules::requestHash($payload);$row=$db->one("SELECT * FROM davvag_credit_idempotency WHERE operation_scope=? AND idempotency_key=? LIMIT 1 FOR UPDATE","ss",array($scope,$key));if($row){if(!hash_equals($row->request_hash,$hash))throw new CreditException("The idempotency key was already used with different parameters.");if($row->processing_status==="COMPLETED"&&$row->safe_response)return(object)array("replay"=>true,"response"=>json_decode($row->safe_response));throw new CreditException("The operation is already processing.");}$db->insert("davvag_credit_idempotency",array("idempotency_key"=>$key,"operation_scope"=>$scope,"request_hash"=>$hash,"processing_status"=>"PROCESSING","result_transaction_id"=>0,"safe_response"=>"","created_at"=>date("Y-m-d H:i:s"),"expires_at"=>date("Y-m-d H:i:s",time()+2592000)));return(object)array("replay"=>false);}
    private function completeIdempotency($db,$scope,$key,$txId,$response){$row=$db->one("SELECT id FROM davvag_credit_idempotency WHERE operation_scope=? AND idempotency_key=? LIMIT 1","ss",array($scope,$key));$db->updateById("davvag_credit_idempotency",$row->id,array("processing_status"=>"COMPLETED","result_transaction_id"=>intval($txId),"safe_response"=>json_encode($response)));}
    private function createTransaction($db,$program,$type,$context,$originalId=0){$id=$db->insert("davvag_credit_transaction",array("program_id"=>intval($program->id),"external_id"=>"credit_tx_".bin2hex(random_bytes(10)),"idempotency_key"=>$context["idempotencyKey"],"transaction_type"=>strtoupper($type),"status"=>"POSTED","source_app"=>$context["sourceApp"],"reference_type"=>$context["referenceType"],"reference_id"=>$context["referenceId"],"original_transaction_id"=>intval($originalId),"description"=>$context["description"],"metadata_json"=>isset($context["metadata"])?$context["metadata"]:array(),"effective_at"=>date("Y-m-d H:i:s"),"posted_at"=>date("Y-m-d H:i:s"),"actor_profile_id"=>intval(isset($context["actorProfileId"])?$context["actorProfileId"]:0),"actor_user_id"=>strval(isset($context["actorUserId"])?$context["actorUserId"]:"")));return$db->one("SELECT * FROM davvag_credit_transaction WHERE id=?","i",array($id));}
    private function issuanceWallet($source){$source=strtoupper($source);if(in_array($source,array("REWARD","DAILY_REWARD","WEEKLY_REWARD","MONTHLY_REWARD"),true))return"REWARD_ISSUANCE";if(in_array($source,array("COUPON","COUPON_GIFT"),true))return"COUPON_ISSUANCE";if(in_array($source,array("PURCHASE","PACKAGE_BONUS"),true))return"PURCHASE_ISSUANCE";if($source==="REFUND")return"REFUND_CLEARING";return"ADMIN_ADJUSTMENT";}
    private function balanceResult($tx,$amount,$wallet,$posted,$reserved,$available,$replay=false){return(object)array("transactionId"=>intval($tx->id),"externalId"=>$tx->external_id,"amount"=>intval($amount),"status"=>"POSTED","idempotentReplay"=>$replay,"balance"=>(object)array("posted"=>intval($posted),"reserved"=>intval($reserved),"available"=>intval($available),"version"=>intval($wallet->balance_version)+1));}
    public function credit($profileId,$amount,$context,$sourceType="ADMIN",$expiresAt=null,$refundable=false,$sideEffect=null){$amount=CreditRules::amount($amount);$context=$this->normalizeContext($context);$payload=array("profileId"=>intval($profileId),"amount"=>$amount,"context"=>$context,"sourceType"=>$sourceType,"expiresAt"=>$expiresAt);return$this->db->transaction(function($db)use($profileId,$amount,$context,$sourceType,$expiresAt,$refundable,$sideEffect,$payload){$program=$this->programIn($db,isset($context["programCode"])?$context["programCode"]:"CREDIT",true);$idem=$this->beginIdempotency($db,"credit",$context["idempotencyKey"],$payload);if($idem->replay){$idem->response->idempotentReplay=true;return$idem->response;}$wallet=$this->ensureWalletRow($db,$program,intval($profileId),"USER_WALLET");$this->assertWallet($wallet);$system=$this->ensureWalletRow($db,$program,0,$this->issuanceWallet($sourceType));$tx=$this->createTransaction($db,$program,$sourceType,$context);$posted=intval($wallet->posted_balance)+$amount;$available=intval($wallet->available_balance)+$amount;$systemPosted=intval($system->posted_balance)-$amount;$db->run("UPDATE davvag_credit_wallet SET posted_balance=?,available_balance=?,balance_version=balance_version+1 WHERE id=?","iii",array($posted,$available,$wallet->id));$db->run("UPDATE davvag_credit_wallet SET posted_balance=?,available_balance=?,balance_version=balance_version+1 WHERE id=?","iii",array($systemPosted,intval($system->available_balance)-$amount,$system->id));$lotId=$db->insert("davvag_credit_lot",array("wallet_id"=>intval($wallet->id),"program_id"=>intval($program->id),"origin_transaction_id"=>intval($tx->id),"source_type"=>strtoupper($sourceType),"original_amount"=>$amount,"remaining_amount"=>$amount,"expires_at"=>$expiresAt,"refundable"=>$refundable?"true":"false","status"=>"ACTIVE"));$db->insert("davvag_credit_entry",array("transaction_id"=>intval($tx->id),"wallet_id"=>intval($wallet->id),"direction"=>"CREDIT","amount"=>$amount,"credit_lot_id"=>$lotId,"balance_after"=>$posted,"description"=>$context["description"]));$db->insert("davvag_credit_entry",array("transaction_id"=>intval($tx->id),"wallet_id"=>intval($system->id),"direction"=>"DEBIT","amount"=>$amount,"credit_lot_id"=>0,"balance_after"=>$systemPosted,"description"=>$context["description"]));if(is_callable($sideEffect))$sideEffect($db,$tx,$wallet,$lotId);$response=$this->balanceResult($tx,$amount,$wallet,$posted,intval($wallet->reserved_balance),$available);$this->completeIdempotency($db,"credit",$context["idempotencyKey"],$tx->id,$response);return$response;});}
    private function consumeLots($db,$walletId,$amount){$remaining=$amount;$allocations=array();$lots=$db->all("SELECT * FROM davvag_credit_lot WHERE wallet_id=? AND status='ACTIVE' AND remaining_amount>0 AND (expires_at IS NULL OR expires_at>NOW()) ORDER BY CASE WHEN expires_at IS NOT NULL THEN 0 WHEN source_type='PURCHASE' THEN 2 ELSE 1 END, expires_at ASC, id ASC FOR UPDATE","i",array($walletId));foreach($lots as$lot){if($remaining<=0)break;$take=min($remaining,intval($lot->remaining_amount));$left=intval($lot->remaining_amount)-$take;$db->updateById("davvag_credit_lot",$lot->id,array("remaining_amount"=>$left,"status"=>$left===0?"DEPLETED":"ACTIVE"));$allocations[]=array("lotId"=>intval($lot->id),"amount"=>$take);$remaining-=$take;}if($remaining>0)throw new CreditException("Credit lots do not cover the requested amount.");return$allocations;}
    public function debit($profileId,$amount,$context,$sideEffect=null,$reservation=null){$amount=CreditRules::amount($amount);$context=$this->normalizeContext($context);$scope=$reservation?"capture-reservation":"debit";$payload=array("profileId"=>intval($profileId),"amount"=>$amount,"context"=>$context,"reservationId"=>$reservation?intval($reservation->id):0);return$this->db->transaction(function($db)use($profileId,$amount,$context,$sideEffect,$reservation,$scope,$payload){$program=$this->programIn($db,isset($context["programCode"])?$context["programCode"]:"CREDIT",true);$idem=$this->beginIdempotency($db,$scope,$context["idempotencyKey"],$payload);if($idem->replay){$idem->response->idempotentReplay=true;return$idem->response;}$wallet=$this->ensureWalletRow($db,$program,intval($profileId),"USER_WALLET");$this->assertWallet($wallet);$reserved=intval($wallet->reserved_balance);$available=intval($wallet->available_balance);if($reservation){$locked=$db->one("SELECT * FROM davvag_credit_reservation WHERE id=? AND wallet_id=? LIMIT 1 FOR UPDATE","ii",array($reservation->id,$wallet->id));if(!$locked||$locked->status!=="ACTIVE")throw new CreditException("The reservation is not active.");if(intval($locked->amount)!==$amount)throw new CreditException("Reservation amount mismatch.");$reserved-=$amount;}elseif($available<$amount)throw new CreditException("Insufficient available credit balance.");$allocations=$this->consumeLots($db,$wallet->id,$amount);$system=$this->ensureWalletRow($db,$program,0,"SPEND_DESTINATION");$tx=$this->createTransaction($db,$program,$reservation?"RESERVATION_CAPTURE":"SPEND",$context);$posted=intval($wallet->posted_balance)-$amount;if(!$reservation)$available-=$amount;$systemPosted=intval($system->posted_balance)+$amount;$running=intval($wallet->posted_balance);foreach($allocations as$allocation){$running-=$allocation["amount"];$db->insert("davvag_credit_entry",array("transaction_id"=>intval($tx->id),"wallet_id"=>intval($wallet->id),"direction"=>"DEBIT","amount"=>$allocation["amount"],"credit_lot_id"=>$allocation["lotId"],"balance_after"=>$running,"description"=>$context["description"]));}$db->insert("davvag_credit_entry",array("transaction_id"=>intval($tx->id),"wallet_id"=>intval($system->id),"direction"=>"CREDIT","amount"=>$amount,"credit_lot_id"=>0,"balance_after"=>$systemPosted,"description"=>$context["description"]));$db->run("UPDATE davvag_credit_wallet SET posted_balance=?,reserved_balance=?,available_balance=?,balance_version=balance_version+1 WHERE id=?","iiii",array($posted,$reserved,$available,$wallet->id));$db->run("UPDATE davvag_credit_wallet SET posted_balance=?,available_balance=?,balance_version=balance_version+1 WHERE id=?","iii",array($systemPosted,intval($system->available_balance)+$amount,$system->id));if($reservation)$db->updateById("davvag_credit_reservation",$reservation->id,array("status"=>"CAPTURED","captured_transaction_id"=>intval($tx->id)));if(is_callable($sideEffect))$sideEffect($db,$tx,$wallet,$allocations);$response=$this->balanceResult($tx,$amount,$wallet,$posted,$reserved,$available);$this->completeIdempotency($db,$scope,$context["idempotencyKey"],$tx->id,$response);return$response;});}
    public function reserve($profileId,$amount,$context,$expiresAt=null){$amount=CreditRules::amount($amount);$context=$this->normalizeContext($context);$payload=array("profileId"=>intval($profileId),"amount"=>$amount,"context"=>$context,"expiresAt"=>$expiresAt);return$this->db->transaction(function($db)use($profileId,$amount,$context,$expiresAt,$payload){$program=$this->programIn($db,isset($context["programCode"])?$context["programCode"]:"CREDIT",true);$idem=$this->beginIdempotency($db,"reserve",$context["idempotencyKey"],$payload);if($idem->replay){$idem->response->idempotentReplay=true;return$idem->response;}$wallet=$this->ensureWalletRow($db,$program,intval($profileId),"USER_WALLET");$this->assertWallet($wallet);if(intval($wallet->available_balance)<$amount)throw new CreditException("Insufficient available credit balance.");$id=$db->insert("davvag_credit_reservation",array("wallet_id"=>intval($wallet->id),"program_id"=>intval($program->id),"amount"=>$amount,"idempotency_key"=>$context["idempotencyKey"],"source_app"=>$context["sourceApp"],"reference_type"=>$context["referenceType"],"reference_id"=>$context["referenceId"],"status"=>"ACTIVE","expires_at"=>$expiresAt?:date("Y-m-d H:i:s",time()+900),"captured_transaction_id"=>0,"released_at"=>null));$reserved=intval($wallet->reserved_balance)+$amount;$available=intval($wallet->available_balance)-$amount;$db->run("UPDATE davvag_credit_wallet SET reserved_balance=?,available_balance=?,balance_version=balance_version+1 WHERE id=?","iii",array($reserved,$available,$wallet->id));$response=(object)array("reservationId"=>$id,"amount"=>$amount,"status"=>"ACTIVE","idempotentReplay"=>false,"balance"=>(object)array("posted"=>intval($wallet->posted_balance),"reserved"=>$reserved,"available"=>$available,"version"=>intval($wallet->balance_version)+1));$this->completeIdempotency($db,"reserve",$context["idempotencyKey"],0,$response);return$response;});}
